            {
                if (isLine(bwImageBorders, i, middlewidth, 12) && isLine(bwImageBorders, i, middleWidth2, 12))
                {

                    int prevLine = checkPrevLine(middlewidth, middleWidth2, i, bwImageBorders, 12);

                    lastHeigh = prevLine;
                    if (lastHeigh < i && (i - lastHeigh) > 12)
                    {

                        int cutHeight = int.Parse(Math.Round((i - lastHeigh) * 1.0, 0).ToString());

                        var Row = CropRow(imgbw, cutWidth, cutHeight, 0, lastHeigh, "" + imagePath, row.ToString(), false);
                        var Row2 = CropRow(bwImageBorders, cutWidth, cutHeight, 0, lastHeigh, "" + imagePath, row + "borders", false);
